CREATE TABLE IF NOT EXISTS richo_third_party_dependencies(id uuid PRIMARY KEY,name text NOT NULL,category text NOT NULL,criticality text NOT NULL,provider text,services jsonb NOT NULL DEFAULT '[]'::jsonb,sla jsonb NOT NULL DEFAULT '{}'::jsonb,security jsonb NOT NULL DEFAULT '{}'::jsonb,alternatives jsonb NOT NULL DEFAULT '[]'::jsonb,version jsonb NOT NULL DEFAULT '{}'::jsonb,data_access jsonb NOT NULL DEFAULT '[]'::jsonb,status text NOT NULL DEFAULT 'active',correlation_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_third_party_risk_snapshots(id uuid PRIMARY KEY,dependency_id uuid NOT NULL REFERENCES richo_third_party_dependencies(id) ON DELETE CASCADE,assessment jsonb NOT NULL,telemetry jsonb NOT NULL DEFAULT '{}'::jsonb,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_third_party_incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dependency_id uuid NOT NULL REFERENCES richo_third_party_dependencies(id),severity text NOT NULL,impact jsonb NOT NULL,status text NOT NULL DEFAULT 'open',started_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS richo_third_party_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dependency_id uuid NOT NULL REFERENCES richo_third_party_dependencies(id) ON DELETE CASCADE,review_type text NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,result text NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now(),next_review_at timestamptz);
CREATE INDEX IF NOT EXISTS richo_third_party_provider_idx ON richo_third_party_dependencies(provider,criticality,status);
